use std::io::Cursor;
use image::{AnimationDecoder,ImageDecoder, ImageFormat, ImageReader, Limits};
static mut OUT:[u32;6]=[0;6];
#[no_mangle] pub extern "C" fn alloc(len:usize)->*mut u8{let mut v=vec![0u8;len];let p=v.as_mut_ptr();std::mem::forget(v);p}
#[no_mangle] pub unsafe extern "C" fn dealloc(ptr:*mut u8,len:usize){drop(Vec::from_raw_parts(ptr,len,len));}
#[no_mangle] pub unsafe extern "C" fn output(index:usize)->u32{if index<6{OUT[index]}else{0}}
fn limits()->Limits{let mut l=Limits::default();l.max_image_width=Some(1024);l.max_image_height=Some(1024);l.max_alloc=Some(24*1024*1024);l}
fn animated<'a>(d:impl AnimationDecoder<'a>,w:u32,h:u32)->Result<[u32;6],String>{let mut count=0;let mut ms=0u32;let mut pixels=0u64;for frame in d.into_frames(){let f=frame.map_err(|e|e.to_string())?;count+=1;pixels+=u64::from(w)*u64::from(h);if count>60||pixels>8_000_000{return Err("budget".into());}let(n,den)=f.delay().numer_denom_ms();if den==0{return Err("delay".into());}ms=ms.checked_add(n/den).ok_or("overflow")?;if ms>10_000{return Err("duration".into());}}if count==0{return Err("empty".into());}Ok([w,h,count,ms,pixels as u32,1])}
fn framing(b:&[u8],fmt:ImageFormat)->Result<(),String>{match fmt{ImageFormat::Png=>{let mut p=8usize;let mut ended=false;while p+12<=b.len(){let n=u32::from_be_bytes(b[p..p+4].try_into().unwrap()) as usize;if n>b.len()-p-12{return Err("png bounds".into());}let kind=&b[p+4..p+8];if kind==b"acTL"{return Err("apng".into());}let crc=u32::from_be_bytes(b[p+8+n..p+12+n].try_into().unwrap());if crc32fast::hash(&b[p+4..p+8+n])!=crc{return Err("png crc".into());}p+=12+n;if kind==b"IEND"{ended=n==0&&p==b.len();break;}}if !ended{return Err("png end".into());}},ImageFormat::Jpeg=>{if !b.ends_with(&[255,217]){return Err("jpeg eoi".into());}},ImageFormat::WebP=>{if b.len()<12||u32::from_le_bytes(b[4..8].try_into().unwrap()) as usize!=b.len()-8{return Err("webp riff length".into());}},_=>{}}Ok(())}
fn validate_inner(b:&[u8])->Result<[u32;6],String>{if b.len()>1_048_576{return Err("bytes".into());}let fmt=image::guess_format(b).map_err(|e|e.to_string())?;framing(b,fmt)?;match fmt{ImageFormat::Gif=>{let mut d=image::codecs::gif::GifDecoder::new(Cursor::new(b)).map_err(|e|e.to_string())?;d.set_limits(limits()).map_err(|e|e.to_string())?;let(w,h)=d.dimensions();animated(d,w,h)},ImageFormat::WebP=>{let mut d=image::codecs::webp::WebPDecoder::new(Cursor::new(b)).map_err(|e|e.to_string())?;d.set_limits(limits()).map_err(|e|e.to_string())?;let(w,h)=d.dimensions();if d.has_animation(){animated(d,w,h)}else{let mut raw=vec![0;d.total_bytes() as usize];d.read_image(&mut raw).map_err(|e|e.to_string())?;Ok([w,h,1,0,w*h,2])}},ImageFormat::Jpeg=>{let options=zune_core::options::DecoderOptions::default().set_strict_mode(true).set_max_width(1024).set_max_height(1024);let mut d=zune_jpeg::JpegDecoder::new_with_options(zune_core::bytestream::ZCursor::new(b),options);let raw=d.decode().map_err(|e|e.to_string())?;let(w,h)=d.dimensions().ok_or("dimensions")?;if raw.is_empty(){return Err("empty".into());}Ok([w as u32,h as u32,1,0,(w*h) as u32,4])},ImageFormat::Png=>{let mut r=ImageReader::with_format(Cursor::new(b),fmt);r.limits(limits());let img=r.decode().map_err(|e|e.to_string())?;Ok([img.width(),img.height(),1,0,img.width()*img.height(),if fmt==ImageFormat::Png{3}else{4}])},_=>Err("unsupported".into())}}
#[no_mangle]pub unsafe extern "C" fn validate(ptr:*const u8,len:usize)->u32{match validate_inner(std::slice::from_raw_parts(ptr,len)){Ok(v)=>{OUT=v;0},Err(_)=>{OUT=[0;6];1}}}
